cd ~/.claude/projects/-home-user-guidebook/ && python3 - <<'PY'
import json
lines=open('f8d4d6c2-8f72-53c6-8e31-d3258750c5f6.jsonl').read().splitlines()
out=[]
for l in lines[-200:]:
    try: d=json.loads(l)
    except: continue
    m=d.get('message',{})
    c=m.get('content')
    if isinstance(c,list):
        for x in c:
            if x.get('type')=='text' and d.get('type') in('user','assistant'): out.append((d['type'],x['text'][:1500]))
            if x.get('type')=='tool_use': 
                inp=x.get('input',{}); s=json.dumps(inp)[:600]
                if 'adjud' in s.lower() or 'Q-B' in s or 'Q3' in s: out.append(('tool',s))
    elif isinstance(c,str) and d.get('type')=='user': out.append(('user',c[:1500]))
for t,s in out[-25:]: print('---',t); print(s)
PY

